// CUDA WebShader 0.1.1. Generated from kernel scatter_clip_slots.
@group(0) @binding(0) var<storage, read> b_valid: array<u32>;
@group(0) @binding(1) var<storage, read> b_offsets: array<u32>;
@group(0) @binding(2) var<storage, read> b_blocks: array<u32>;
@group(0) @binding(3) var<storage, read_write> b_compact_valid: array<u32>;
struct CWParams {
  p_slot_count: u32,
  cw_pad_4: u32,
  cw_pad_8: u32,
  cw_pad_12: u32,
}
@group(0) @binding(4) var<uniform> cw_params: CWParams;
const cw_block_size: vec3<u32> = vec3<u32>(64u, 1u, 1u);


@compute @workgroup_size(64, 1, 1)
fn main(
  @builtin(local_invocation_id) cw_thread: vec3<u32>,
  @builtin(workgroup_id) cw_block: vec3<u32>,
  @builtin(num_workgroups) cw_grid: vec3<u32>
) {
  var v_i: u32 = (((cw_block.x + (cw_block.y * cw_grid.x)) * cw_block_size.x) + cw_thread.x);
  if (((v_i >= cw_params.p_slot_count) || (b_valid[v_i] == 0u))) {
    return;
  }
  b_compact_valid[(b_blocks[(v_i / 256u)] + b_offsets[v_i])] = (2147483648u | v_i);
}

